param([switch]$PassThru)
$ErrorActionPreference='Stop'; $tmp=Join-Path ([IO.Path]::GetTempPath()) ('beijixing-alignment-'+[Guid]::NewGuid().ToString('n'));New-Item -ItemType Directory -Path $tmp -Force|Out-Null;$inputPath=Join-Path $tmp 'fixture.json';$calculatorPath=Join-Path $PSScriptRoot 'calculate-enterprise-plan-impact.ps1'
$fixture=[ordered]@{plan=[ordered]@{plan_id='bundle-A';version='v3';owner_id='operations-owner';deadline='2026-08-20';success_condition='120 bundles available'};baseline_requirements=@([ordered]@{resource_id='X';required_quantity=100},[ordered]@{resource_id='Y';required_quantity=100},[ordered]@{resource_id='Z';required_quantity=100});requirements=@([ordered]@{requirement_id='req-X';plan_id='bundle-A';resource_id='X';required_quantity=120;responsible_role='supply_chain_manager'},[ordered]@{requirement_id='req-Y';plan_id='bundle-A';resource_id='Y';required_quantity=120;responsible_role='supply_chain_manager'},[ordered]@{requirement_id='req-Z';plan_id='bundle-A';resource_id='Z';required_quantity=120;responsible_role='supply_chain_manager'});resources=@([ordered]@{resource_id='X';available_quantity=35;owner_id='procurement-owner';evidence_refs=@('inventory://X')},[ordered]@{resource_id='Y';available_quantity=120;owner_id='warehouse-owner';evidence_refs=@('inventory://Y')},[ordered]@{resource_id='Z';available_quantity=60;owner_id='procurement-owner';evidence_refs=@('inventory://Z')});commitments=@([ordered]@{commitment_id='X-PO';resource_id='X';committed_quantity=40;eta='2026-08-15';status='confirmed';owner_id='procurement-owner';evidence_status='verified';evidence_refs=@('po://X')},[ordered]@{commitment_id='Z-late';resource_id='Z';committed_quantity=50;eta='2026-08-25';status='shipped';owner_id='procurement-owner';evidence_status='verified';evidence_refs=@('shipment://Z')},[ordered]@{commitment_id='Z-unverified';resource_id='Z';committed_quantity=50;eta='2026-08-10';status='confirmed';owner_id='procurement-owner';evidence_status='pending';evidence_refs=@()})};[IO.File]::WriteAllText($inputPath,($fixture|ConvertTo-Json -Depth 10),[Text.UTF8Encoding]::new($false));$raw=@(& powershell.exe -NoProfile -ExecutionPolicy Bypass -File $calculatorPath -InputPath $inputPath -PassThru 2>&1);$code=$LASTEXITCODE;$report=(($raw|ForEach-Object{$_.ToString()})-join"`n")|ConvertFrom-Json;$x=@($report.items|Where-Object resource_id -eq 'X')[0];$y=@($report.items|Where-Object resource_id -eq 'Y')[0];$z=@($report.items|Where-Object resource_id -eq 'Z')[0];$zException=@($report.exceptions|Where-Object resource_id -eq 'Z')[0]
$cases=@([pscustomobject]@{name='version_delta_is_quantified';passed=($x.version_impact-eq20-and$z.version_impact-eq20)},[pscustomobject]@{name='only_verified_on_time_commitment_counts';passed=($x.on_time_committed_supply-eq40-and$z.on_time_committed_supply-eq0)},[pscustomobject]@{name='gap_and_exceptions_route_to_responsible_owner';passed=($x.resource_gap-eq45-and$y.resource_gap-eq0-and$z.resource_gap-eq60-and$zException.responsible_owner_id-eq'procurement-owner')},[pscustomobject]@{name='late_and_unverified_commitments_are_visible_risk';passed=(@($z.late_commitment_ids).Count-eq1-and@($z.unverified_commitment_ids).Count-eq1)},[pscustomobject]@{name='report_cannot_execute_business_action';passed=($code-eq0-and$report.execution_authorized-eq$false-and$report.business_write_performed-eq$false)})
$contract=Get-Content -LiteralPath (Join-Path $PSScriptRoot 'cross-functional-alignment-contract.json') -Raw -Encoding UTF8|ConvertFrom-Json;$cases += [pscustomobject]@{name='field_ownership_and_L4_boundary_are_explicit';passed=(@($contract.field_ownership.plan_owner_may_not_change)-contains'commitment.eta'-and$contract.field_ownership.all_external_or_business_writes-eq'Enterprise_L4_separate_grant_approval_readback')}
$failed=@($cases|Where-Object{-not$_.passed});$out=[pscustomobject]@{passed=($failed.Count-eq0);cases=$cases;external_calls=$false;business_write=$false};if($PassThru){$out|ConvertTo-Json -Depth 8}else{$cases|Format-Table -AutoSize};if($failed.Count){throw('Cross-functional alignment regression failed: '+(($failed.name)-join', '))}
